    """Return the Fahrenheit equivalent of a Celsius temperature."""
    raise NotImplementedError

solution:
def celsius_to_f(celsius):
    """Return the Fahrenheit equivalent of a Celsius temperature."""
    return celsius * 9 / 5 + 32

