solution:
def grade(score):
    """Return the letter grade for a score from 0 to 100."""
    if score >= 90:
        return "A"
    if score >= 80:
        return "B"
    if score >= 70:
        return "C"
    if score >= 60:
        return "D"
    return "F"

starter:
def is_leap_year(year):
    """Return True if year is a leap year."""
    raise NotImplementedError

solution:
def is_leap_year(year):
    """Return True if year is a leap year."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

starter:
def classify_triangle(a, b, c):
    """Return 'equilateral', 'isosceles', 'scalene', or 'invalid'."""
    raise NotImplementedError

solution:
def classify_triangle(a, b, c):
    """Return 'equilateral', 'isosceles', 'scalene', or 'invalid'."""
    if a <= 0 or b <= 0 or c <= 0:
        return "invalid"
    if a + b <= c or a + c <= b or b + c <= a:
        return "invalid"
    if a == b == c:
        return "equilateral"
    if a == b or b == c or a == c:
        return "isosceles"
    return "scalene"

