    """Return the prime factors of n in ascending order, with repeats."""
    raise NotImplementedError

solution:
def prime_factors(n):
    """Return the prime factors of n in ascending order, with repeats."""
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    divisor = 3
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 2
    if n > 1:
        factors.append(n)
    return factors

starter:
def collatz_length(n):
    """Return the number of Collatz steps needed to reach 1."""
    raise NotImplementedError

solution:
def collatz_length(n):
    """Return the number of Collatz steps needed to reach 1."""
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps
